from django.db import models
from apps.common.models import TimeStampedModel
class Order(TimeStampedModel):
    PAYMENT_STATUS=[('pending','pending'),('paid','paid'),('failed','failed'),('refunded','refunded')]; ORDER_STATUS=[('draft','draft'),('pending_payment','pending_payment'),('processing','processing'),('completed','completed'),('cancelled','cancelled')]; SHIPPING_STATUS=[('not_shipped','not_shipped'),('preparing','preparing'),('shipped','shipped'),('delivered','delivered'),('returned','returned')]
    user=models.ForeignKey('accounts.User', null=True, blank=True, related_name='orders', on_delete=models.SET_NULL); total=models.PositiveBigIntegerField(default=0); discount=models.PositiveBigIntegerField(default=0); shipping_cost=models.PositiveBigIntegerField(default=0); payment_status=models.CharField(max_length=30, choices=PAYMENT_STATUS, default='pending'); order_status=models.CharField(max_length=30, choices=ORDER_STATUS, default='pending_payment'); shipping_status=models.CharField(max_length=30, choices=SHIPPING_STATUS, default='not_shipped'); tracking_code=models.CharField(max_length=120, blank=True); address=models.JSONField(default=dict); payment_reference=models.CharField(max_length=160, blank=True)
class OrderItem(models.Model):
    order=models.ForeignKey(Order, related_name='items', on_delete=models.CASCADE); product=models.ForeignKey('products.Product', null=True, on_delete=models.SET_NULL); product_name=models.CharField(max_length=255); sku=models.CharField(max_length=100); quantity=models.PositiveIntegerField(); unit_price=models.PositiveBigIntegerField(); line_total=models.PositiveBigIntegerField()
